// Main Sidebar component - provides navigation for dashboard pages
export default function Sidebar() {
  const navigate = useNavigate();
  const [showLogoutModal, setShowLogoutModal] = useState(false);
  const handleLogout = () => {
    localStorage.removeItem('authToken');
    localStorage.removeItem('userEmail');
    localStorage.removeItem('userName');
    navigate('/');
    setShowLogoutModal(false);
  };
  return (
    <aside className="h-screen w-64 bg-gradient-to-b from-gray-50 to-white border-r border-gray-200 shadow-lg px-5 py-6 flex flex-col sticky top-0">
      
      {/* Sidebar header with branding */}
      <div className="flex flex-col items-center mb-8 pb-6 border-b border-gray-200">
        <img 
          src="/logo2.jpeg" 
          alt="ZPIN Logo" 
          className="h-16 w-16 rounded-2xl object-cover shadow-md mb-3"
        />
        <div className="font-bold text-xl text-gray-800 mb-1">
          ZPIN Seller Hub
        </div>
        <div className="text-gray-500 text-xs font-medium tracking-wide">
          Manage your Business
        </div>
        <div className="mt-3">
          <NotificationBell />
        </div>
      </div>
      
      {/* Navigation menu */}
      <nav className="flex-1 overflow-y-auto scrollbar-hide">
        <ul className="space-y-1.5">
          {sidebarLinks.map(link => (
            <li key={link.label}>
              
              {/* Navigation link with active state styling */}
              <NavLink
                to={link.to}
                end={link.to === '/dashboard'}
                className={({ isActive }) =>
                  `flex items-center gap-3 px-4 py-3 rounded-xl font-semibold text-sm transition-all duration-200 group ${
                    isActive
                      ? 'bg-brand text-white shadow-md scale-105'
                      : 'text-gray-700 hover:bg-orange-50 hover:text-brand hover:translate-x-1'
                  }`
                }
              >
                <span>{link.icon}</span>
                <span className="flex-1">{link.label}</span>
              </NavLink>
              
            </li>
          ))}
        </ul>
      </nav>
      
      {/* Logout button */}
      <div className="mt-auto pt-6 border-t border-gray-200">
        <button
          onClick={() => setShowLogoutModal(true)}
          className="w-full flex items-center justify-center gap-3 px-4 py-3.5 rounded-xl font-semibold text-sm text-gray-700 bg-gray-100 hover:bg-red-50 hover:text-red-600 hover:border-red-200 transition-all duration-200 shadow-sm hover:shadow-md border border-gray-200 group"
        >
          <svg className="w-5 h-5 transition-transform group-hover:scale-110" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 96 96">
            <path stroke="currentColor" strokeLinecap="round" strokeWidth="5" d="M44 78H57C60.3137 78 63 75.3137 63 72V56.5M12 61V16C12 12.6863 14.6863 10 18 10H57C60.3137 10 63 12.6863 63 16V33"></path>
            <path stroke="currentColor" strokeWidth="5" d="M12 18.8864C12 14.6352 16.2993 11.7324 20.2425 13.3213L37.2425 20.1713C39.5129 21.0862 41 23.2886 41 25.7365V81.1136C41 85.3649 36.7007 88.2676 32.7575 86.6787L15.7575 79.8287C13.4871 78.9138 12 76.7114 12 74.2635V18.8864Z"></path>
            <path stroke="currentColor" strokeLinecap="round" strokeWidth="5" d="M79 54L84.818 48.182C86.5754 46.4246 86.5754 43.5754 84.818 41.818L79 36M76 45H52"></path>
          </svg> 
          <span>Log Out</span>
        </button>
      </div>
      
      {/* Logout Confirmation Modal */}
      <LogoutModal 
        isOpen={showLogoutModal}
        onClose={() => setShowLogoutModal(false)}
        onConfirm={handleLogout}
      />
      
    </aside>
  );
}